//! Static account data extracted from the upstream calculators.
//!
//! Every table here is generated by `script/extract-account-data.mjs` from
//! `Corgan/idleon-research-optimizer`; nothing is hand-typed. The research grid
//! data lives next door in `research.json`.

use serde::Deserialize;
use std::collections::BTreeMap;
use std::sync::OnceLock;

const ACCOUNT_JSON: &str = include_str!("../../../data/account.json");

/// The account tables the save decoder reads.
#[derive(Debug, Deserialize)]
pub struct AccountData {
    /// The game's character encoding for event shop, superbit and emporium
    /// lists: item `t` is owned when the list contains `encoding[t]`.
    pub encoding: String,
    /// Arcade shop parameters by upgrade index: `[formula, x1, x2]`.
    pub arcade: BTreeMap<String, (String, f64, f64)>,
    #[serde(rename = "rogBonus")]
    pub rog_bonus: Vec<f64>,
    #[serde(rename = "mineheadBonus")]
    pub minehead_bonus: Vec<f64>,
    #[serde(rename = "meritocBase")]
    pub meritoc_base: Vec<f64>,
    #[serde(rename = "arenaThresholds")]
    pub arena_thresholds: Vec<f64>,
    #[serde(rename = "petArenaThresholds")]
    pub pet_arena_thresholds: Vec<f64>,
    #[serde(rename = "godTypes")]
    pub god_types: Vec<f64>,
    #[serde(rename = "jellyReward")]
    pub jelly_reward: Vec<f64>,
    #[serde(rename = "stickerBase")]
    pub sticker_base: Vec<f64>,
    #[serde(rename = "dancingCoralBase")]
    pub dancing_coral_base: Vec<f64>,
    #[serde(rename = "menagerieBoost")]
    pub menagerie_boost: Vec<f64>,
    #[serde(rename = "cardBaseReq")]
    pub card_base_req: BTreeMap<String, f64>,
    #[serde(rename = "equipmentSets")]
    pub equipment_sets: BTreeMap<String, f64>,
    #[serde(rename = "nametagTier")]
    pub nametag_tier: Vec<f64>,
    pub nametags: BTreeMap<String, Vec<(String, f64)>>,
    pub trophies: BTreeMap<String, Vec<(String, f64)>>,
    pub hats: BTreeMap<String, Vec<(String, f64)>>,
    pub capes: BTreeMap<String, Vec<(String, f64)>>,
    /// Item UQ stats: `[stat 1, value 1, stat 2, value 2]`.
    pub items: BTreeMap<String, (String, f64, String, f64)>,
    #[serde(rename = "etcStats")]
    pub etc_stats: BTreeMap<String, String>,
    #[serde(rename = "labBonus")]
    pub lab_bonus: Vec<(f64, f64, f64, f64, f64, String)>,
    #[serde(rename = "labDynamic")]
    pub lab_dynamic: Vec<(f64, f64, f64, f64, f64, String, u32)>,
    pub jewels: Vec<(f64, f64, f64, String)>,
    #[serde(rename = "vaultPerLevel")]
    pub vault_per_level: Vec<f64>,
    #[serde(rename = "legendPerPoint")]
    pub legend_per_point: Vec<f64>,
    #[serde(rename = "spelunkUpgPerLevel")]
    pub spelunk_upg_per_level: Vec<f64>,
    /// Exotic market upgrades: `{base, decay, denom}` by index.
    pub exotic: BTreeMap<String, ExoticParam>,
    pub artifacts: Vec<f64>,
    /// Tome slots: `[half, mode, max points]`.
    pub tome: Vec<(f64, f64, f64)>,
    #[serde(rename = "deathNoteMobs")]
    pub death_note_mobs: Vec<Vec<(i64, f64)>>,
    #[serde(rename = "deathNoteMobNames")]
    pub death_note_mob_names: Vec<Vec<String>>,
    #[serde(rename = "dungeonRankThresholds")]
    pub dungeon_rank_thresholds: Vec<f64>,
    #[serde(rename = "petWorldPets")]
    pub pet_world_pets: Vec<Vec<String>>,
    #[serde(rename = "petShinyType")]
    pub pet_shiny_type: Vec<Vec<Option<u32>>>,
    #[serde(rename = "shinyTypeToCat")]
    pub shiny_type_to_cat: Vec<u32>,
    #[serde(rename = "shinyBonusPerLevel")]
    pub shiny_bonus_per_level: Vec<f64>,
    #[serde(rename = "summonNormalBonus")]
    pub summon_normal_bonus: BTreeMap<String, (Option<f64>, Option<f64>)>,
    #[serde(rename = "summonEndlessType")]
    pub summon_endless_type: Vec<f64>,
    #[serde(rename = "summonEndlessVal")]
    pub summon_endless_val: Vec<f64>,
    #[serde(rename = "emperorBonusType")]
    pub emperor_bonus_type: Vec<f64>,
    #[serde(rename = "emperorBonusVal")]
    pub emperor_bonus_val: Vec<f64>,
    #[serde(rename = "companionBonus")]
    pub companion_bonus: Vec<f64>,
    #[serde(rename = "companionEnhanced")]
    pub companion_enhanced: Vec<f64>,
    #[serde(rename = "chipEffects")]
    pub chip_effects: Vec<String>,
    #[serde(rename = "vaultNoMastery")]
    pub vault_no_mastery: Vec<u32>,
    pub palette: BTreeMap<String, PaletteParam>,
    #[serde(rename = "paletteSuperbitPairs")]
    pub palette_superbit_pairs: Vec<(u32, u32)>,
    #[serde(rename = "arcanePerLevel")]
    pub arcane_per_level: Vec<f64>,
    #[serde(rename = "arcaneNoMulti")]
    pub arcane_no_multi: Vec<u32>,
    pub bubbles: Bubbles,
}

/// One gaming palette's curve.
#[derive(Debug, Deserialize)]
pub struct PaletteParam {
    pub coeff: f64,
    pub decay: bool,
    pub denom: f64,
}

/// One exotic market upgrade's curve.
#[derive(Debug, Deserialize)]
pub struct ExoticParam {
    pub base: f64,
    pub decay: bool,
    pub denom: f64,
}

/// The alchemy bubble the gallery reads (`CODFREY_RULZ_OK`, Kazam 32).
#[derive(Debug, Deserialize)]
pub struct Bubbles {
    pub y13: BubbleParam,
}

#[derive(Debug, Deserialize)]
pub struct BubbleParam {
    pub cauldron: usize,
    pub index: usize,
    pub x1: f64,
    pub x2: f64,
    pub formula: String,
}

impl AccountData {
    /// Arcade shop parameters at an upgrade index.
    pub fn arcade(&self, index: usize) -> Option<(&str, f64, f64)> {
        self.arcade
            .get(&index.to_string())
            .map(|(formula, x1, x2)| (formula.as_str(), *x1, *x2))
    }

    /// An exotic market upgrade's curve.
    pub fn exotic(&self, index: usize) -> Option<&ExoticParam> {
        self.exotic.get(&index.to_string())
    }

    /// A gaming palette's curve.
    pub fn palette(&self, index: usize) -> Option<&PaletteParam> {
        self.palette.get(&index.to_string())
    }

    /// The companion bonus at `index`, normal or enhanced.
    pub fn companion(&self, index: usize, enhanced: bool) -> f64 {
        let table = if enhanced {
            &self.companion_enhanced
        } else {
            &self.companion_bonus
        };
        table.get(index).copied().unwrap_or(0.0)
    }

    /// The stat name an `EtcBonuses` id feeds.
    pub fn etc_stat(&self, index: usize) -> Option<&str> {
        self.etc_stats.get(&index.to_string()).map(String::as_str)
    }

    /// A set bonus by name.
    pub fn set_bonus(&self, name: &str) -> f64 {
        self.equipment_sets.get(name).copied().unwrap_or(0.0)
    }
}

/// The account tables, parsed once.
pub fn account_data() -> &'static AccountData {
    static DATA: OnceLock<AccountData> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(ACCOUNT_JSON).expect("bundled account data is valid JSON")
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn account_data_covers_the_research_tree() {
        let data = account_data();
        assert_eq!(data.rog_bonus.len(), 64);
        assert_eq!(data.minehead_bonus.len(), 32);
        assert_eq!(data.jelly_reward.len(), 72);
        assert_eq!(data.tome.len(), 124);
        assert!(data.etc_stat(108).is_some(), "equipment research EXP stat");
        assert!(data.arcade(63).is_some(), "arcade 63");
        assert!(data.arcade(59).is_some(), "arcade 59");
        assert!(!data.items.is_empty());
        assert!(data.set_bonus("PREHISTORIC_SET") > 0.0);
    }
}
